        assert_eq!(cfg.ctx_seed, Some(serde_json::json!({"tenant": "acme"})));
    }

    #[test]
    fn ctx_seed_defaults_none() {
        assert_eq!(TemporalRunnerConfig::new("q").ctx_seed, None);
    }
