/// Run the driver loop, racing it against the run-deadline timer and workflow
/// cancellation. Always returns a total outcome.
async fn drive(
    ctx: &WorkflowContext<DurableAgentWorkflow>,
    config: Arc<WorkflowActivityConfig>,
    input: WorkflowInput,
) -> DurableRunOutcome {
    let agent_name = input.agent_name.clone();
    let timeout_ms = input.timeout_ms;
    let parallel_limit = input.config.parallel_tool_call_limit;
    let ctx_seed = input.ctx_seed.clone();

    // Single keyed lookup — deterministic, not a `HashMap` iteration.
    let plan = match config.plans.get(&agent_name) {
        Some(plan) => plan.clone(),
        None => return unknown_agent_outcome(&agent_name),
    };

    let mut driver = DurableDriver::new(input, plan);

    // Race the whole effect loop against (a) the durable run-deadline timer
    // and (b) cooperative cancellation. The `select!` block owns the borrow of
    // `driver` (via `effects`); it is released at the block's end, before
    // `driver.interrupt(..)` consumes the driver on an interruption. A natural
    // finish `return`s the outcome directly from inside the loop.
    let interrupt = {
        let effects = run_effects(
            ctx,
            &config,
            &agent_name,
            &ctx_seed,
            parallel_limit,
            &mut driver,
        )
        .fuse();
        let deadline = run_deadline(ctx, timeout_ms).fuse();
        let cancelled = ctx.cancelled();
        futures_util::pin_mut!(effects, deadline, cancelled);

        temporalio_sdk::workflows::select! {
            outcome = effects => return outcome,
            _ = deadline => InterruptKind::TimedOut,
            _ = cancelled => InterruptKind::Cancelled,
        }
    };

    driver.interrupt(interrupt)
}

/// The run-deadline future: a durable timer of `timeout_ms`, or a never-
/// resolving future when no deadline is configured.
async fn run_deadline(ctx: &WorkflowContext<DurableAgentWorkflow>, timeout_ms: Option<u64>) {
    match timeout_ms {
        Some(ms) => {
            let _ = ctx.timer(Duration::from_millis(ms)).await;
        }
        None => futures_util::future::pending::<()>().await,
    }
}

/// Execute driver effects one activity at a time until the driver reports a
/// terminal outcome.
async fn run_effects(
    ctx: &WorkflowContext<DurableAgentWorkflow>,
    config: &WorkflowActivityConfig,
    agent_name: &str,
    ctx_seed: &Option<serde_json::Value>,
    parallel_limit: Option<usize>,
    driver: &mut DurableDriver,
) -> DurableRunOutcome {
    loop {
        match driver.next_effect() {
            DriverEffect::RenderInstructions => {
                match ctx
                    .start_activity(
                        AgentActivities::render_instructions,
                        RenderInstructionsArgs {
                            agent_name: agent_name.to_owned(),
                            ctx_seed: ctx_seed.clone(),
                        },
                        config.instructions_activity_opts.clone(),
                    )
                    .await
                {
                    Ok(system_text) => driver.apply_instructions(system_text),
                    // An infra-level failure of the (otherwise deterministic)
                    // render step is terminal — surface it like a model
                    // failure so the run finalizes with events-so-far.
                    Err(err) => driver.apply_model_failure(extract_error_kind(&err)),
                }
            }
            DriverEffect::CallModel(request) => {
                match ctx
                    .start_activity(
                        AgentActivities::call_model,
                        CallModelArgs {
                            agent_name: agent_name.to_owned(),
                            request,
                        },
                        config.model_activity_opts.clone(),
                    )
                    .await
                {
                    Ok(turn) => driver.apply_model(turn),
                    // ADR-10: `call_model` marks model errors non-retryable and
                    // carries an `ErrorKindPayload` JSON in the failure — parse
                    // it back and feed the terminal failure to the driver.
                    Err(err) => driver.apply_model_failure(extract_error_kind(&err)),
                }
            }
            DriverEffect::ExecuteTools(calls) => {
                let outcomes =
                    execute_tools(ctx, config, agent_name, ctx_seed, parallel_limit, calls).await;
                driver.apply_tools(outcomes);

    /// Append-only, bounded event log for this run.
    pub log: Arc<EventLog>,
    /// Cancellation token — drop or call `.cancel()` to abort the run.
    pub cancel: CancellationToken,
    /// Populated on the start-error path when the agent failed to launch before emitting any events.
    pub start_error: Mutex<Option<String>>,
    /// Set once the run enters a terminal state (via [`RunRegistry::note_terminal`]).
    pub terminal_at: Mutex<Option<Instant>>,
    /// When the run was created. Used by the sweeper to reclaim a run that never
    /// reaches a terminal state.
    pub created_at: Instant,
}

/// Public `error` text for a run that failed before emitting any event.
///
/// The detailed cause is logged once by the writer task; putting it in the
/// frame would leak it to every SSE and WebSocket subscriber (CWE-209).
const PUBLIC_RUN_FAILED_TO_START: &str = "run failed to start";

/// Public `error` text for a stream that ended without a terminal event.
const PUBLIC_RUN_NO_TERMINAL: &str = "run ended before producing a terminal event";

impl RunHandle {
    /// The synthetic terminal frame a streaming transport must emit when its
    /// subscribe stream ended without delivering a real `RunCompleted`/`RunFailed`.
    ///
    /// Returns `None` when a real terminal was already delivered (`saw_terminal`
    /// is `true`). Otherwise returns an [`AgentEvent::RunFailed`], carrying
    /// [`PUBLIC_RUN_FAILED_TO_START`] if the run failed to start, or
    /// [`PUBLIC_RUN_NO_TERMINAL`] otherwise (e.g. a stream that panicked or
    /// ended mid-run before any terminal event). Both are fixed public strings —
    /// the detailed cause never reaches this frame (CWE-209).
    pub(crate) fn synthetic_terminal_frame(&self, saw_terminal: bool) -> Option<AgentEvent> {
        if saw_terminal {
            return None;
        }
        let failed_to_start = self
            .start_error
            .lock()
            .expect("start_error mutex poisoned")
            .is_some();
        let error = if failed_to_start {
            PUBLIC_RUN_FAILED_TO_START
        } else {
            PUBLIC_RUN_NO_TERMINAL
        };
        // Note this logs the PUBLIC string, not the detail. The detail is logged
        // once by the writer task; this method runs once per subscriber, so
        // logging it here would duplicate it per subscriber and skip it entirely
        // for an unwatched run.
        tracing::warn!(
            agent = %self.agent_name,
            %error,
            "run ended without a real terminal event; synthesizing a RunFailed frame for the stream subscriber"
        );
        Some(AgentEvent::RunFailed {
            error: error.to_owned(),
        })
    }
}

