#[async_trait]
pub trait Runner<Ctx>: Send + Sync
where
    Ctx: Send + Sync + 'static,
{
    /// Run the agent to completion and return the aggregated result.
    ///
    /// **With a `Session`** (always present on [`RunContext`]): the runner loads
    /// persisted history at start and seeds the conversation as
    /// `history ++ input.messages`, so `input` is the *new turn* — the session
    /// owns history. The run's events are persisted at exit. To continue with no
    /// new turn (or to retry a failed run without re-appending the user message),
    /// use [`Runner::resume`].
    ///
    /// **The returned future must be polled to completion for the run's events to
    /// be persisted.** Finalization happens inside this future, so — as with any
    /// future — dropping it early cancels the work still in flight, including the
    /// session write, and the turn is lost. A caller that cannot guarantee it will
    /// poll to completion (an HTTP handler whose client may disconnect, say) should
    /// drive the run on a detached task and await its result over a channel, rather
    /// than awaiting it inline.
    ///
    /// **Conversely, this future issues the session write before it resolves**, so
    /// callers may treat its resolution as an ordering barrier: the finalize step is
    /// ordered before `run` returns, not left in flight behind it. This is what makes
    /// "detach and await the result over a channel" a sufficient remedy for the hazard
    /// above. Note this is an ordering guarantee, not a durability one: persistence is
    /// best-effort, so an implementation may log rather than propagate an append
    /// failure, and a run that fails before the agent starts never reaches finalize at
    /// all.
    ///
    /// **Cancellation/timeout is best-effort and loses to a genuine terminal
    /// event that already occurred.** If the run reaches a terminal
    /// (`RunCompleted`/`RunFailed`) before — or in the same poll as — a cancel or
    /// timeout, the runner reports that real outcome (`Ok`, or the structured
    /// `Err(RunError::Agent(..))`), not `Err(RunError::Cancelled)` /
    /// `Err(RunError::Timeout)`. The cancel/timeout wins only when it aborted the
    /// run in-flight, before any terminal event. A caller therefore cannot assume
    /// "I called `cancel()` ⇒ I get `Cancelled`".
    async fn run(
        &self,
        agent: &(dyn Agent<Ctx> + '_),
        ctx: RunContext<Ctx>,
        input: AgentInput,
        config: RunConfig,
    ) -> Result<RunResult, RunError>;

    /// Run the agent and return a streaming result handle.
    ///
    /// Session loading/seeding matches [`Runner::run`]. **The returned stream
    /// must be driven to its terminal for the run's events to be persisted:** a
    /// consumer that drops the stream early may skip the finalize step and leave
    /// a partial turn (or nothing) written.
    ///
    /// The same cancellation precedence as [`Runner::run`] applies: once a real
    /// terminal event has been yielded, a late cancel/timeout does not append a
    /// second, synthetic terminal — the stream ends after the real one.
    async fn run_streamed(
        &self,
        agent: &(dyn Agent<Ctx> + '_),
        ctx: RunContext<Ctx>,
        input: AgentInput,
        config: RunConfig,
    ) -> Result<RunResultStreaming, RunError>;

    /// Resume a run from the session's persisted history with no new input.
    ///
    /// Equivalent to [`Runner::run`] with an empty [`AgentInput`]: the runner
    /// loads the conversation from `ctx.session()` and continues it. Use this to
    /// continue a multi-turn session, or to retry a failed run without
    /// re-appending the previous turn's user message. (With a `Session` present,
    /// [`Runner::run`]'s `input` is the *new turn*; the session owns history.)
    async fn resume(
        &self,
        agent: &(dyn Agent<Ctx> + '_),
        ctx: RunContext<Ctx>,
        config: RunConfig,
    ) -> Result<RunResult, RunError> {
        self.run(agent, ctx, AgentInput::new(), config).await
    }

    /// Streaming counterpart of [`Runner::resume`]: resumes from session
    /// history with no new input and returns a streaming result handle instead
    /// of an aggregated [`RunResult`].
    async fn resume_streamed(
        &self,
        agent: &(dyn Agent<Ctx> + '_),
        ctx: RunContext<Ctx>,
        config: RunConfig,
    ) -> Result<RunResultStreaming, RunError> {
        self.run_streamed(agent, ctx, AgentInput::new(), config)
            .await
    }
}

/// Per-run configuration.
///
/// SMA-314 shipped `max_turns`; SMA-321 added `timeout` and
/// `parallel_tool_call_limit`. Cancellation is intentionally *not* a field
/// here — the canonical token lives on [`crate::RunContext`].
#[derive(Debug, Clone)]
#[non_exhaustive]
pub struct RunConfig {
    /// `[driver-scoped]` Maximum number of model turns before the loop fails
    /// with [`crate::AgentError::MaxTurnsExceeded`]. Honored by the core loop
    /// driver, including on a bare `agent.run()` with no runner. Default `16`.
    pub max_turns: u32,
    /// `[runner-scoped]` Wall-clock deadline for the whole run. Honored ONLY by
    /// a runtime backend (e.g. `TokioRunner`); a bare `agent.run()` cannot time
    /// out (core has no timer). `None` = no deadline.
    pub timeout: Option<Duration>,
    /// `[driver-scoped]` Cap on concurrently-executing tool calls. Honored by
    /// the core loop driver. `None` = unbounded (today's behavior).
    pub parallel_tool_call_limit: Option<NonZeroUsize>,
    /// `[driver-scoped]` Maximum agent-nesting depth across **both** handoff
    /// chains and `AgentAsTool` sub-runs. Each nested agent run increments the
    /// depth; exceeding this fails with
    /// [`crate::AgentError::MaxAgentDepthExceeded`]. Default `8`.
    pub max_agent_depth: u32,
}

impl Default for RunConfig {
    fn default() -> Self {
        Self {
            max_turns: 16,
            timeout: None,
            parallel_tool_call_limit: None,
            max_agent_depth: 8,
        }
    }
}

impl RunConfig {
    /// Construct a default config (`max_turns = 16`).
    pub fn new() -> Self {
        Self::default()
    }

